    private static void buildInitialHeap(int[] heap, int[] weight, int[] parent, int alphaSize) {
        int nHeap = 0;
        heap[0] = 0;
        weight[0] = 0;
        parent[0] = -2;

        for (int i = 1; i <= alphaSize; i++) {
            parent[i] = -1;
            nHeap++;
            heap[nHeap] = i;
            heapifyUp(heap, weight, nHeap);
        }
    }

    private static void heapifyUp(int[] heap, int[] weight, int index) {
        int zz = index;
        int tmp = heap[zz];
        while (weight[tmp] < weight[heap[zz >> 1]]) {
            heap[zz] = heap[zz >> 1];
            zz >>= 1;
        }
        heap[zz] = tmp;
    }

    private static void buildHuffmanTree(int[] heap, int[] weight, int[] parent, int alphaSize) {
        int nNodes = alphaSize;
        int nHeap = alphaSize;

        while (nHeap > 1) {
            int n1 = extractMin(heap, weight, nHeap);
            nHeap--;
            int n2 = extractMin(heap, weight, nHeap);
            nHeap--;

            nNodes++;
            parent[n1] = parent[n2] = nNodes;

            weight[nNodes] = combineWeights(weight[n1], weight[n2]);
            parent[nNodes] = -1;
            nHeap++;
            heap[nHeap] = nNodes;
            heapifyUp(heap, weight, nHeap);
        }
    }

    private static int extractMin(int[] heap, int[] weight, int nHeap) {
        int n1 = heap[1];
        heap[1] = heap[nHeap];

        int zz = 1;
        int tmp = heap[1];
        while (true) {
            int yy = zz << 1;
            if (yy > nHeap) {
                break;
            }
            if ((yy < nHeap) && (weight[heap[yy + 1]] < weight[heap[yy]])) {
                yy++;
            }
            if (weight[tmp] < weight[heap[yy]]) {
                break;
            }
            heap[zz] = heap[yy];
            zz = yy;
        }
        heap[zz] = tmp;
        return n1;
    }

    private static int combineWeights(int w1, int w2) {
        return ((w1 & 0xffffff00) + (w2 & 0xffffff00))
            | (1 + (((w1 & 0x000000ff) > (w2 & 0x000000ff))
                    ? (w1 & 0x000000ff) : (w2 & 0x000000ff)));
    }

    private static void updateCodeLengths(char[] len, int[] parent, int alphaSize, int maxLen, boolean tooLong) {
        for (int i = 1; i <= alphaSize; i++) {
            int j = 0;
            int k = i;
            for (int parent_k; (parent_k = parent[k]) >= 0;) {
                k = parent_k;
                j++;
            }
            len[i - 1] = (char) j;
            if (j > maxLen) {
                tooLong = true;
            }
        }
    }

