 public String[] dissect(String path) {
    char sep = File.separatorChar;
    path = path.replace('/', sep).replace('\\', sep);

    if (!isAbsolutePath(path)) {
        throw new BuildException(path + " is not an absolute path");
    }

    String root = computeRoot(path);
    String remainingPath = path.substring(root.length());

    // Normalize path: eliminate consecutive separators
    remainingPath = normalizeRemainingPath(remainingPath, sep);

    return new String[] {root, remainingPath};
}

/**
 * Computes the root portion of an absolute path.
 * @param path normalized absolute path ( separators already converted)
 * @return the root component (drive+colon on DOS/Netware, UNC prefix, or File.separator)
 */
private String computeRoot(String path) {
    int colon = path.indexOf(':');
    if (colon > 0 && (ON_DOS || ON_NETWARE)) {
        int next = colon + 1;
        String root = path.substring(0, next);
        root += File.separatorChar;
        int start = (next < path.length() && path.charAt(next) == File.separatorChar)
                ? next + 1 : next;
        // root already includes trailing separator, so remaining starts at 'start'
        return path.substring(0, start);
    } else if (path.length() > 1 && path.charAt(1) == File.separatorChar) {
        // UNC drive
        int nextsep = path.indexOf(File.separatorChar, 2);
        nextsep = path.indexOf(File.separatorChar, nextsep + 1);
        return (nextsep > 2) ? path.substring(0, nextsep + 1) : path;
    } else {
        return File.separator;
    }
}

/**
 * Normalizes the remaining path portion by removing consecutive separators.
 * @param path remaining path portion
 * @param sep system-dependent file separator
 * @return normalized remaining path without consecutive separators
 */
private String normalizeRemainingPath(String path, char sep) {
    StringBuilder sb = new StringBuilder();
    boolean lastWasSeparator = false;
    for (int i = 0; i < path.length(); i++) {
        char c = path.charAt(i);
        if (c == sep) {
            if (!lastWasSeparator) {
                sb.append(c);
            }
            lastWasSeparator = true;
        } else {
            sb.append(c);
            lastWasSeparator = false;
        }
    }
    return sb.toString();
}

protected void compile() {
    if (compileList.length == 0) {
        return;
    }

    logCompilationInfo();
