private void processArgs(String[] args) {
    ArgumentProcessorRegistry processorRegistry = ArgumentProcessorRegistry.getInstance();
    ArgProcessorContext context = new ArgProcessorContext(args);

    for (int i = 0; i < args.length; i++) {
        String arg = args[i];
        if (!processSingleArg(arg, i, context, processorRegistry)) {
            // Not a recognized option, treat as target
            targets.addElement(arg);
        }
    }

    processPostArgumentPhase(context);
}

/**
 * Processes a single command-line argument and updates context accordingly.
 * Returns true if argument was recognized and processed.
 *
 * @param arg the current argument to evaluate
 * @param i current index in args array
 * @param context shared processing context
 * @param registry registry of argument processors
 * @return true if argument was handled, false otherwise
 */
private boolean processSingleArg(String arg, int i, ArgProcessorContext context,
        ArgumentProcessorRegistry registry) {
    if (isStandardOption(arg)) {
        handleStandardOption(arg, context);
        return true;
    }

    if (arg.startsWith("-D")) {
        handleArgDefine(args, i);
        return true;
    }

    if (isSpecialOption(arg)) {
        handleSpecialOptions(arg, context, i);
        return true;
    }

    // Try registered argument processors
    for (ArgumentProcessor processor : registry.getProcessors()) {
        int newI = processor.readArguments(args, i);
        if (newI != -1) {
            collectExtraArgs(processor.getClass(), args, i, newI);
            return true;
        }
    }

    return false;
}

/**
 * Handles standard short options like -help, -version, etc.
 */
private void handleStandardOption(String arg, ArgProcessorContext context) {
    switch (arg) {
        case "-help": case "-h":
            context.setJustPrintUsage(true);
            break;
        case "-version":
            context.setJustPrintVersion(true);
            break;
        case "-diagnostics":
            context.setJustPrintDiagnostics(true);
            break;
        case "-quiet": case "-q":
            msgOutputLevel = Project.MSG_WARN;
            break;
        case "-verbose": case "-v":
            msgOutputLevel = Project.MSG_VERBOSE;
            break;
        case "-debug": case "-d":
            msgOutputLevel = Project.MSG_DEBUG;
            break;
        case "-silent": case "-S":
            context.setSilent(true);
            break;
        case "-noinput":
            context.setAllowInput(false);
            break;
        case "-emacs": case "-e":
            context.setEmacsMode(true);
            break;
        case "-projecthelp": case "-p":
            context.setProjectHelp(true);
            break;
        case "-k": case "-keep-going":
            context.setKeepGoingMode(true);
            break;
        case "-autoproxy":
            context.setProxy(true);
            break;
        default:
            // Not a recognized short option
    }
}

/**
 * Handles special options requiring additional argument processing.
 */
private void handleSpecialOptions(String arg, ArgProcessorContext context, int i) {
    if ("-logfile".equals(arg) || "-l".equals(arg)) {
        context.setLogTo(processLogfileArg(i));
    } else if ("-buildfile".equals(arg) || "-file".equals(arg) || "-f".equals(arg)) {
        i = handleArgBuildFile(args, i);
    } else if ("-listener".equals(arg)) {
        i = handleArgListener(args, i);
    } else if ("-logger".equals(arg)) {
        i = handleArgLogger(args, i);
    } else if ("-inputhandler".equals(arg)) {
        i = handleArgInputHandler(args, i);
    } else if ("-propertyfile".equals(arg)) {
        i = handleArgPropertyFile(args, i);
    } else if ("-nice".equals(arg)) {
        i = handleArgNice(args, i);
    } else if ("-find".equals(arg) || "-s".equals(arg)) {
        processFindOption(args, i, context);
    } else if (LAUNCH_COMMANDS.contains(arg)) {
        throw launchCommandMismatch(arg);
    } else if (arg.startsWith("-")) {
        // Unknown option handled elsewhere
    }
}

/**
 * Processes the -find/-s option and populates search context.
 */
private void processFindOption(String[] args, int i, ArgProcessorContext context) {
    context.setSearchForFile(true);
    if (i < args.length - 1) {
        context.setSearchForThis(args[++i]);
    }
}

/**
 * Handles post-argument processing including version printing,
 * diagnostics reporting, and default build file resolution.
 */
private void processPostArgumentPhase(ArgProcessorContext context) {
    maybePrintVersion(context);
    maybePrintHelpOrDiagnostics(context);
    resolveBuildFile(context);
    normalizeAndValidateBuildFile();
    loadPropertyFiles();
    setupOutputStreams(context.getLogTo());
}

/**
 * Prints version if either verbose output or --version flag is set.
 */
private void maybePrintVersion(ArgProcessorContext context) {
    if (msgOutputLevel >= Project.MSG_VERBOSE || context.isJustPrintVersion()) {
        printVersion(msgOutputLevel);
    }
}

/**
 * Handles --help and --diagnostics outputs if requested.
 */
private void maybePrintHelpOrDiagnostics(ArgProcessorContext context) {
    if (context.isJustPrintUsage() || context.isJustPrintDiagnostics()
            || context.isJustPrintVersion()) {
        if (context.isJustPrintUsage()) {
            printUsage();
        }
        if (context.isJustPrintDiagnostics()) {
            Diagnostics.doReport(System.out, msgOutputLevel);
        }
        return;
    }
}

/**
 * Determines build file location if not explicitly provided.
 */
private void resolveBuildFile(ArgProcessorContext context) {
    if (buildFile == null) {
        if (context.isSearchForFile()) {
            searchBuildFile(context.getSearchForThis());
        } else {
            fallbackToDefaultBuildFile();
        }
    }
}

/**
 * Searches for build file using user-provided suffix.
 */
private void searchBuildFile(String searchFile) {
    String suffix = searchFile != null ? searchFile : null;

    if (suffix != null) {
        buildFile = findBuildFile(System.getProperty("user.dir"), suffix);
        if (buildFile == null) {
            throw new BuildException("Could not locate a build file!");
        }
    } else {
        fallbackToDefaultBuildFile();
    }
}

/**
 * Attempts to locate a default build file by trying all registered helpers.
 */
private void fallbackToDefaultBuildFile() {
    Iterator<ProjectHelper> it = ProjectHelperRepository.getInstance().getHelpers();
    do {
        ProjectHelper helper = it.next();
        buildFile = new File(helper.getDefaultBuildFile());
        if (msgOutputLevel >= Project.MSG_VERBOSE) {
            System.out.println("Trying the default build file: " + buildFile);
        }
    } while (!buildFile.exists() && it.hasNext());

    if (!buildFile.exists()) {
        throw new BuildException("Could not locate a build file!");
    }
}

/**
 * Validates the build file exists and is not a directory.
 */
private void normalizeAndValidateBuildFile() {
    if (!buildFile.exists()) {
        System.out.println("Buildfile: " + buildFile + " does not exist!");
        throw new BuildException("Build failed");
    }

    if (buildFile.isDirectory()) {
        File inferredBuildFile = new File(buildFile, "build.xml");
        if (inferredBuildFile.isFile()) {
            buildFile = inferredBuildFile;
        } else {
            System.out.println("What? Buildfile: " + buildFile + " is a dir!");
            throw new BuildException("Build failed");
        }
    }

    buildFile = FileUtils.getFileUtils().normalize(buildFile.getAbsolutePath());
}

