private static final class BuildConnectionStrategy {
    private final Object metaTypesObj;
    private final MetaTypes metaTypes;

    BuildConnectionStrategy(MetaTypes mt) {
        this.metaTypesObj = mt;
        this.metaTypes = mt;
    }

    Object buildConnection(Object elementType, Object fromElement,
            Object fromStyle, Object toElement, Object toStyle,
            Object unidirectional, Object namespace) {

        if (elementType == metaTypesObj) {
            return handleAssociation(elementType, fromElement, fromStyle,
                    toElement, toStyle, unidirectional);
        }
        if (elementType == metaTypes.getAssociationEnd()) {
            return handleAssociationEnd(fromElement, toElement);
        }
        if (elementType == metaTypes.getAssociationClass()) {
            return handleAssociationClass(fromElement, toElement);
        }
        if (elementType == metaTypes.getAssociationRole()) {
            return handleAssociationRole(fromElement, fromStyle, toElement,
                    toStyle, unidirectional);
        }
        if (elementType == metaTypes.getGeneralization()) {
            return handleGeneralization(fromElement, toElement);
        }
        if (elementType == metaTypes.getPackageImport()) {
            return handlePackageImport(fromElement, toElement);
        }
        if (elementType == metaTypes.getUsage()) {
            return handleUsage(fromElement, toElement);
        }
        if (elementType == metaTypes.getDependency()) {
            return handleDependency(fromElement, toElement);
        }
        if (elementType == metaTypes.getAbstraction()) {
            return handleAbstraction(fromElement, toElement, namespace);
        }
        if (elementType == metaTypes.getLink()) {
            return handleLink(fromElement, toElement);
        }
        if (elementType == metaTypes.getExtend()) {
            return handleExtend(toElement, fromElement);
        }
        if (elementType == metaTypes.getInclude()) {
            return handleInclude(fromElement, toElement);
        }
        if (elementType == metaTypes.getTransition()) {
            return handleTransition(fromElement, toElement);
        }
        return null;
    }

    private Object handleAssociation(Object elementType, Object fromElement,
            Object fromStyle, Object toElement, Object toStyle,
            Object unidirectional) {
        return getCore().buildAssociation(fromElement,
                fromStyle, toElement,
                toStyle, ((Boolean) unidirectional).booleanValue());
    }

    private Object handleAssociationEnd(Object fromElement, Object toElement) {
        if (fromElement instanceof UmlAssociation) {
            return getCore().buildAssociationEnd(toElement, fromElement);
        } else if (fromElement instanceof Classifier) {
            return getCore().buildAssociationEnd(fromElement, toElement);
        }
        return null;
    }

    private Object handleAssociationClass(Object fromElement, Object toElement) {
        return getCore().buildAssociationClass(fromElement, toElement);
    }

    private Object handleAssociationRole(Object fromElement, Object fromStyle,
            Object toElement, Object toStyle, Object unidirectional) {
        return getCollaborations().buildAssociationRole(fromElement,
                fromStyle, toElement, toStyle,
                ((Boolean) unidirectional).booleanValue());
    }

    private Object handleGeneralization(Object fromElement, Object toElement) {
        return getCore().buildGeneralization(fromElement, toElement);
    }

    private Object handlePackageImport(Object fromElement, Object toElement) {
        return getCore().buildPackageImport(fromElement, toElement);
    }

    private Object handleUsage(Object fromElement, Object toElement) {
        return getCore().buildUsage(fromElement, toElement);
    }

    private Object handleDependency(Object fromElement, Object toElement) {
        return getCore().buildDependency(fromElement, toElement);
    }

    private Object handleAbstraction(Object fromElement, Object toElement,
            Object namespace) {
        return getCore().buildRealization(fromElement, toElement, namespace);
    }

    private Object handleLink(Object fromElement, Object toElement) {
        return getCommonBehavior().buildLink(fromElement, toElement);
    }

    private Object handleExtend(Object toElement, Object fromElement) {
        return getUseCases().buildExtend(toElement, fromElement);
    }

