    if (classifier != null) {
        return findTopLevelNamespace(classifier);
    }
    return null;
}

private Namespace findTopLevelNamespace(Classifier classifier) {
    Namespace parent = classifier.getNamespace();
    while (parent instanceof Classifier) {
        if (parent.getNamespace() == null) {
            break;
        }
        parent = parent.getNamespace();
    }
    return parent;
}

