public Object findOperationByName(Object trans, String opname) {
    if (!(trans instanceof Transition)) {
        throw new IllegalArgumentException();
    }

    try {
        Object sm = getStateMachine(trans);
        Object context = Model.getFacade().getContext(sm);
        Classifier classifier = extractClassifier(context);
        if (classifier != null) {
            Object result = findOperationInClassifier(classifier, opname);
            if (result != null) {
                return result;
            }
        }

        Namespace pack = extractNamespace(context, classifier);
        if (pack != null) {
            Object result = findOperationInNamespace(pack, opname);
            if (result != null) {
                return result;
            }
        }
    } catch (InvalidObjectException e) {
        throw new InvalidElementException(e);
    }

    return null;
}

private Classifier extractClassifier(Object context) {
    if (context instanceof Classifier) {
        return (Classifier) context;
    }
    if (context instanceof BehavioralFeature) {
        return ((BehavioralFeature) context).getOwner();
    }
    return null;
}

private Object findOperationInClassifier(Classifier classifier, String opname) {
    for (Feature f : classifier.getFeature()) {
        if (f instanceof Operation && opname.equals(f.getName())) {
            return f;
        }
    }
    return null;
}

private Namespace extractNamespace(Object context, Classifier classifier) {
    if (context instanceof UmlPackage) {
        return (Namespace) context;
    }
    if (classifier == null) {
        return null;
    }
    return findRootNamespace(classifier.getNamespace());
}

private Namespace findRootNamespace(Namespace ns) {
    Namespace parent = ns;
    while (parent instanceof Classifier && parent.getNamespace() != null) {
        parent = parent.getNamespace();
    }
    return parent instanceof Namespace ? parent : null;
}

private Object findOperationInNamespace(Namespace pack, String opname) {
    for (ModelElement me : pack.getOwnedElement()) {
        if (me instanceof Classifier) {
            Classifier classifier2 = (Classifier) me;
            Object result = findOperationInClassifier(classifier2, opname);
            if (result != null) {
                return result;
            }
        }
    }
    return null;
}

