        File normalized = FILE_UTILS.normalize(baseDir.getAbsolutePath());
        if (!normalized.exists()) {
            throw new BuildException("Basedir " + normalized.getAbsolutePath()
                + " does not exist");
        }
        if (!normalized.isDirectory()) {
            throw new BuildException("Basedir " + normalized.getAbsolutePath()
                + " is not a directory");
        }
        // Only assign after validation succeeds
    }

