def media_property(cls):
    def _media(self):
        base = _get_base_media(cls, self)
        definition = getattr(cls, 'Media', None)
        if definition is None:
            return base

        extend = getattr(definition, 'extend', True)
        if extend is False:
            return Media(definition)

        media = _build_media_with_extension(cls, base, definition, extend)
        return media

    return property(_media)


def _get_base_media(cls, self):
    sup_cls = super(cls, self)
    try:
        return sup_cls.media
    except AttributeError:
        return Media()


def _build_media_with_extension(cls, base, definition, extend):
    if extend is True:
        return base + Media(definition)
    else:
        media = Media()
        for medium in extend:
            media = media + base[medium]
        return media + Media(definition)

        return combined


def _extract_media_from_base_and_definition(sup_cls, cls, cls_name):
    """
    Extract media from superclass and class definition, handling inheritance and extension.

    Returns a Media object combining base and definition media according to 'extend' directive.
    """
    # Get the media property of the superclass, if it exists
    try:
        base = sup_cls.media
    except AttributeError:
        base = Media()

    # Get the media definition for this class
    definition = getattr(cls, 'Media', None)
    if not definition:
        return base

    extend = getattr(definition, 'extend', True)
    if not extend:
        return Media(definition)

    # Handle extend logic
    if extend is True:
        m = base
    else:
        m = Media()
        for medium in extend:
            m = m + base[medium]
    return m + Media(definition)


def media_property(cls):
    def _media(self):
        # Get the media property of the superclass, if it exists
        sup_cls = super(cls, self)
        return _extract_media_from_base_and_definition(sup_cls, cls, cls.__name__)
    return property(_media)


class MediaDefiningClass(type):
    """
    Metaclass for classes that can have media definitions.
    """
    def __new__(mcs, name, bases, attrs):
        new_class = super(MediaDefiningClass, mcs).__new__(mcs, name, bases, attrs)

        if 'media' not in attrs:
            new_class.media = media_property(new_class)

        return new_class

class RegroupNode(Node):
    def __init__(self, target, expression, var_name):
        self.target, self.expression = target, expression
        self.var_name = var_name

    def _resolve_expression_for_obj(self, obj, context):
        """
        Helper method to resolve the grouping expression for a single object.
        Temporarily places the object in context under var_name before resolution.
        """
        context[self.var_name] = obj
        return self.expression.resolve(context, True)

    def render(self, context):
        obj_list = self.target.resolve(context, True)
        if obj_list is None:
            context[self.var_name] = []
            return ''
        context[self.var_name] = [
            GroupedResult(grouper=key, list=list(val))
            for key, val in
            groupby(obj_list, lambda obj: self._resolve_expression_for_obj(obj, context))
        ]
        return ''

    context[self.var_name] = obj
    return self.expression.resolve(context, True)

def render(self, context):
    obj_list = self.target.resolve(context, True)
    if obj_list is None:
        # target variable wasn't found in context; fail silently.
        context[self.var_name] = []
        return ''
    return self._process_regroup(obj_list, context)

def _process_regroup(self, obj_list, context):
    """
    Process regrouping logic and populate context with grouped results.
    """
    grouped = self._group_objects(obj_list, context)
    context[self.var_name] = [
        GroupedResult(grouper=key, list=list(val))
        for key, val in grouped
    ]
    return ''

def _group_objects(self, obj_list, context):
    """
    Group objects by evaluating the expression on each object.
    """
    def get_grouper(obj):
        context.push()
        try:
            context[self.var_name] = obj
            return self.expression.resolve(context, True)
        finally:
            context.pop()

    return groupby(obj_list, get_grouper)

