 * Returns the first successful match, or null if no suitable principal is found.
 */
private Principal findUserViaAuthenticationMethods() throws LoginException {
  // Strategy 1: Kerberos authentication
  if (isAuthenticationMethodEnabled(AuthenticationMethod.KERBEROS)) {
    Principal kerberosUser = getCanonicalUser(KerberosPrincipal.class);
    if (kerberosUser != null) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("using kerberos user:" + kerberosUser);
      }
      return kerberosUser;
    }
  }

  // Strategy 2: Simple mode with environment or system property fallback
  if (!isSecurityEnabled()) {
    String envUser = System.getenv(HADOOP_USER_NAME);
    if (envUser == null) {
      envUser = System.getProperty(HADOOP_USER_NAME);
    }
    if (envUser != null) {
      return new User(envUser);
    }
  }

  // Strategy 3: OS-specific principal extraction
  Principal osPrincipal = getCanonicalUser(OS_PRINCIPAL_CLASS);
  if (osPrincipal != null) {
    if (LOG.isDebugEnabled()) {
      LOG.debug("using local user:" + osPrincipal);
    }
    return osPrincipal;
  }

  return null;
