      // Try something rack local.
      if (!rackNodes.isEmpty()) {
        return (DatanodeDescriptor) (rackNodes
            .get(DFSUtil.getRandom().nextInt(rackNodes.size())));
      }
    }

    // If we can't even choose rack local, just choose any node in the
    // cluster.
    return (DatanodeDescriptor) getNetworkTopology().chooseRandom(NodeBase.ROOT);
