  /**
   * Picks the best node from the list of candidate rack nodes based on
   * machine-local and rack-local heuristics.
   *
   * @param rackNodes  list of candidate nodes in the rack
   * @param targetHost IP address (or host) of the target node
   * @param dnId       original datanode ID parsed from input address
   * @return best-matching DatanodeDescriptor, or null if none available
   */
  private DatanodeDescriptor pickBestNodeFromRack(List<Node> rackNodes,
      String targetHost, DatanodeID dnId) {
    if (rackNodes == null || rackNodes.isEmpty()) {
      // No rack-local candidates -> fall back to random node in cluster
      return (DatanodeDescriptor) getNetworkTopology()
          .chooseRandom(NodeBase.ROOT);
    }

    // Try something machine local.
    for (Node rackNode : rackNodes) {
      if (((DatanodeDescriptor) rackNode).getIpAddr().equals(targetHost)) {
        return (DatanodeDescriptor) rackNode;
      }
    }

    // Try something rack local: choose a random node from the rack
    if (!rackNodes.isEmpty()) {
      return (DatanodeDescriptor) rackNodes
          .get(DFSUtil.getRandom().nextInt(rackNodes.size()));
    }

    // No suitable rack-local candidate -> fall back to random node
    return (DatanodeDescriptor) getNetworkTopology()
        .chooseRandom(NodeBase.ROOT);
  }

