  DatanodeID dnId = parseDNFromHostsEntry(address);
  GetDatanodeDescriptorContext context = new GetDatanodeDescriptorContext(dnId);
  return getDatanodeDescriptorInternal(context);
}

/**
 * Internal method for resolving a DatanodeDescriptor given a context containing
 * the parsed DatanodeID and necessary cluster state.
 *
 * @param context context holding parsed DatanodeID and resolution parameters
 * @return DatanodeDescriptor the best matching node in the cluster
 */
private DatanodeDescriptor getDatanodeDescriptorInternal(
    GetDatanodeDescriptorContext context) {
  DatanodeDescriptor node = getDatanodeByXferAddr(
      context.host, context.xferPort);
  if (node == null) {
    node = getDatanodeByHost(context.host);
  }
  if (node == null) {
    String networkLocation = context.resolveNetworkLocation();

    // If the current cluster doesn't contain the node, fallback to
    // something machine local and then rack local.
    List<Node> rackNodes = getNetworkTopology()
        .getDatanodesInRack(networkLocation);
    if (rackNodes != null) {
      // Try something machine local.
      for (Node rackNode : rackNodes) {
        if (((DatanodeDescriptor) rackNode).getIpAddr().equals(context.host)) {
          node = (DatanodeDescriptor) rackNode;
          break;
        }
      }

      // Try something rack local.
      if (node == null && !rackNodes.isEmpty()) {
        node = (DatanodeDescriptor) (rackNodes
            .get(DFSUtil.getRandom().nextInt(rackNodes.size())));
      }
    }

    // If we can't even choose rack local, just choose any node in the
    // cluster.
    if (node == null) {
      node = (DatanodeDescriptor) getNetworkTopology()
          .chooseRandom(NodeBase.ROOT);
    }
  }
  return node;
}

/**
 * Parameter object for resolving DatanodeDescriptor from DNS/network context.
 */
private static final class GetDatanodeDescriptorContext {
  final String host;
  final int xferPort;
  private final DatanodeID dnId;
  private final DNSToSwitchMapping dnsToSwitchMapping;
  private final boolean rejectUnresolvedTopologyDN;

  GetDatanodeDescriptorContext(DatanodeID dnId) {
    this.dnId = dnId;
    this.host = dnId.getIpAddr();
    this.xferPort = dnId.getXferPort();
    // Capture needed static references at construction time
    this.dnsToSwitchMapping = DatanodeManager.this.dnsToSwitchMapping;
    this.rejectUnresolvedTopologyDN = DatanodeManager.this.rejectUnresolvedTopologyDN;
  }

  String resolveNetworkLocation() {
    try {
      return resolveNetworkLocation(dnId);
    } catch (UnresolvedTopologyException e) {
      LOG.error("Unresolved topology mapping. Using " +
          NetworkTopology.DEFAULT_RACK + " for host " + dnId.getHostName());
      return NetworkTopology.DEFAULT_RACK;
    }
  }

  private String resolveNetworkLocation(DatanodeID node)
      throws UnresolvedTopologyException {
    List<String> names = new ArrayList<String>(1);
    if (dnsToSwitchMapping instanceof CachedDNSToSwitchMapping) {
      names.add(node.getIpAddr());
    } else {
      names.add(node.getHostName());
    }

    List<String> rName = DatanodeManager.this.resolveNetworkLocation(names);
    String networkLocation;
    if (rName == null) {
      LOG.error("The resolve call returned null!");
      throw new UnresolvedTopologyException(
          "Unresolved topology mapping for host " + node.getHostName());
    } else {
      networkLocation = rName.get(0);
    }
    return networkLocation;
  }
