public void processKeyEvent(KeyEvent evt)
{
	if(isClosed())
		return;

	if (shouldSkipEventProcessing(evt))
		return;

	evt = KeyEventWorkaround.processKeyEvent(evt);
	if (evt == null)
		return;

	switch(evt.getID())
	{
