} //}}}

// Helper methods for processKeyEvent() to reduce cognitive complexity

/**
 * Determines whether the key event should be skipped based on focus and bindings.
 */
private boolean shouldSkipEventProcessing(KeyEvent evt)
{
	if (isFocusInJComponent())
	{
		if (isJComponentBound())
			return true;
	}

	if (isFocusInTextComponent())
	{
		if (shouldSkipTextComponentEvent(evt))
			return true;
	}

	return evt.isConsumed();
}

/**
 * Returns true if the focus owner is a JComponent.
 */
private boolean isFocusInJComponent()
{
	return getFocusOwner() instanceof JComponent;
}

/**
 * Returns true if the JComponent has a matching key binding.
 */
private boolean isJComponentBound()
{
	JComponent comp = (JComponent)getFocusOwner();
	InputMap map = comp.getInputMap();
	ActionMap am = comp.getActionMap();

	if (map == null || am == null || !comp.isEnabled())
		return false;

	Object binding = map.get(KeyStroke.getKeyStrokeForEvent(evt));
	return binding != null && am.get(binding) != null;
}

/**
 * Returns true if the focus owner is a JTextComponent.
 */
private boolean isFocusInTextComponent()
{
	return getFocusOwner() instanceof JTextComponent;
}

/**
 * Determines whether a key event in a JTextComponent should be skipped.
 */
private boolean shouldSkipTextComponentEvent(KeyEvent evt)
{
	if (evt.getID() != KeyEvent.KEY_PRESSED)
		return false;

	switch(evt.getKeyCode())
	{
	case KeyEvent.VK_BACK_SPACE:
	case KeyEvent.VK_TAB:
	case KeyEvent.VK_ENTER:
		return true;
	default:
		return false;
	}
}

/**
 * Handles KEY_TYPED events, forwarding to interceptor or input handler.
 */
private void handleKeyTyped(KeyEvent evt)
{
	if (keyEventInterceptor != null)
		keyEventInterceptor.keyTyped(evt);
	else if (inputHandler.isPrefixActive() && !getTextArea().hasFocus())
		inputHandler.keyTyped(evt);
}

/**
 * Handles KEY_PRESSED events, forwarding to interceptor or input handler.
 */
private void handleKeyPressed(KeyEvent evt)
{
	if (keyEventInterceptor != null)
		keyEventInterceptor.keyPressed(evt);
	else
		inputHandler.keyPressed(evt);
}

/**
 * Handles KEY_RELEASED events, forwarding to interceptor or input handler.
 */
private void handleKeyReleased(KeyEvent evt)
{
	if (keyEventInterceptor != null)
		keyEventInterceptor.keyReleased(evt);
	else
		inputHandler.keyReleased(evt);
