// Helper methods for processKeyEvent()

private boolean shouldSkipEventProcessing(KeyEvent evt)
{
	if (evt.isConsumed())
		return true;

	if (getFocusOwner() instanceof JComponent)
	{
		JComponent comp = (JComponent) getFocusOwner();
		if (isKeyBindingHandledInComponent(comp, evt))
			return true;
	}

	if (getFocusOwner() instanceof JTextComponent)
	{
		if (isSpecialKeyInTextComponent(evt))
			return true;

		if (isKeyHandledInTextComponentKeymap(evt))
			return true;
	}

	return false;
}

private boolean isKeyBindingHandledInComponent(JComponent comp, KeyEvent evt)
{
	InputMap map = comp.getInputMap();
	ActionMap am = comp.getActionMap();

	return map != null && am != null && comp.isEnabled()
		&& am.get(map.get(KeyStroke.getKeyStrokeForEvent(evt))) != null;
}

private boolean isSpecialKeyInTextComponent(KeyEvent evt)
{
	if (evt.getID() != KeyEvent.KEY_PRESSED)
		return false;

	switch (evt.getKeyCode())
	{
	case KeyEvent.VK_BACK_SPACE:
	case KeyEvent.VK_TAB:
	case KeyEvent.VK_ENTER:
		return true;
	default:
		return false;
	}
}

private boolean isKeyHandledInTextComponentKeymap(KeyEvent evt)
{
	Keymap keymap = ((JTextComponent) getFocusOwner()).getKeymap();
