 */
private Object[] cloneLabelRelatedObjects() {
    return new Object[]{
        cloneLabelGenerator(),
        cloneLabelDistributor(),
        cloneLegendLabelGenerator(),
        cloneLegendLabelToolTipGenerator(),
        cloneLegendLabelURLGenerator()
    };
}

/**
 * Clones the shape-related attributes.
 *
 * @return  an array of cloned shapes in this order: [legendItemShape].
 */
private Object[] cloneShapeRelatedAttributes() {
    return new Object[]{cloneLegendItemShape()};
}

/**
 * Clones the URL generator.
 *
 * @return  a cloned URL generator or null.
 */
private Object cloneUrlGeneratorObject() {
    return cloneUrlGenerator();
}

/**
 * Clones the explode percentages.
 *
 * @return  a cloned explode percentages map.
 */
private Map<Comparable<?>, Number> cloneExplodePercentagesObject() {
    return cloneExplodePercentages();
}

/**
 * Clones all required attributes for a PiePlot clone operation.
 *
 * @return  an array of cloned objects covering all needed attributes.
 */
private Object[] cloneAllRequiredAttributes() {
    Object[][] clonedData = new Object[6][];
    clonedData[0] = cloneSectionAttributeMaps();
    clonedData[1] = cloneLabelRelatedObjects();
    clonedData[2] = cloneShapeRelatedAttributes();
    clonedData[3] = new Object[]{cloneUrlGeneratorObject()};
    clonedData[4] = new Object[]{cloneExplodePercentagesObject()};
    clonedData[5] = new Object[]{cloneShadowGenerator()};

    List<Object> allClones = new ArrayList<>();
    for (Object[] subArray : clonedData) {
        allClones.addAll(Arrays.asList(subArray));
    }
    return allClones.toArray(new Object[0]);
}

/**
 * Clones a dataset if possible, otherwise returns null.
 *
 * @param originalDataset  the original dataset.
 * @return  a cloned dataset or null.
 */
private PieDataset cloneDatasetIfPossible(PieDataset originalDataset) {
    if (originalDataset != null && originalDataset instanceof PublicCloneable) {
        return (PieDataset) ObjectUtilities.clone(originalDataset);
    }
    return null;
}

/**
 * Clones the original dataset if possible.
 *
 * @return  a cloned dataset or null.
 */
private PieDataset cloneOriginalDataset() {
    return cloneDatasetIfPossible(this.dataset);
}

/**
 * Clones the dataset listener registration if needed for the cloned plot.
 *
 * @param clone  the cloned plot.
 */
private void registerDatasetListenerForClone(PiePlot clone) {
    if (clone.dataset != null) {
        clone.dataset.addChangeListener(clone);
    }
}

/**
 * Clones all required objects with special handling for dataset and
 * listener registration.
 *
 * @return  an array of cloned objects including specially handled data.
 */
private Object[] cloneAllWithDatasetHandling() {
    Object[] result = new Object[cloneAllRequiredAttributes().length + 1];
    System.arraycopy(cloneAllRequiredAttributes(), 0, result, 0,
            cloneAllRequiredAttributes().length);
    result[result.length - 1] = cloneOriginalDataset();
    return result;
}

/**
 * Clones the original dataset and registers listener for clone.
 *
 * @param clone  the cloned plot.
 * @param clonedDataset  the cloned dataset.
 */
private void handleClonedDatasetAndListener(PiePlot clone,
        PieDataset clonedDataset) {
    clone.dataset = clonedDataset;
    registerDatasetListenerForClone(clone);
}

/**
 * Clones all required objects including dataset and listener.
 *
 * @return  the fully cloned PiePlot instance.
 */
private PiePlot createFullClone() {
    PiePlot clone = (PiePlot) super.clone();
    Object[] clonedObjects = cloneAllWithDatasetHandling();

    int index = 0;
    clone.sectionPaintMap = (PaintMap) clonedObjects[index++];
    clone.sectionOutlinePaintMap = (PaintMap) clonedObjects[index++];
    clone.sectionOutlineStrokeMap = (StrokeMap) clonedObjects[index++];
    clone.labelGenerator = (PieSectionLabelGenerator) clonedObjects[index++];
    clone.labelDistributor = (AbstractPieLabelDistributor) clonedObjects[index++];
    clone.legendLabelGenerator = (PieSectionLabelGenerator) clonedObjects[index++];
    clone.legendLabelToolTipGenerator = (PieSectionLabelGenerator) clonedObjects[index++];
    clone.legendLabelURLGenerator = (PieURLGenerator) clonedObjects[index++];
    clone.legendItemShape = (Shape) clonedObjects[index++];
    clone.urlGenerator = (PieURLGenerator) clonedObjects[index++];
    clone.explodePercentages = (Map<Comparable<?>, Number>) clonedObjects[index++];
    clone.shadowGenerator = (ShadowGenerator) clonedObjects[index++];

    PieDataset clonedDataset = (PieDataset) clonedObjects[index++];
    handleClonedDatasetAndListener(clone, clonedDataset);

    return clone;
}

/**
 * Performs the clone operation using new copy constructor semantics.
 *
 * @return  a clone of this plot.
 *
 * @throws CloneNotSupportedException if cloning is not supported.
 */
private Object performClone() throws CloneNotSupportedException {
    PiePlot clone = createFullClone();
    return clone;
}

/**
 * Implements the public clone method using new copy constructor approach.
 *
 * @return  a cloned instance of the plot.
 *
 * @throws CloneNotSupportedException if cloning is not supported.
 */
@Override
public Object clone() throws CloneNotSupportedException {
    return performClone();
}

 * @throws CloneNotSupportedException if the theme cannot be cloned.
 */
@Override
public Object clone() throws CloneNotSupportedException {
    StandardChartTheme clone = (StandardChartTheme) super.clone();
    if (this.drawingSupplier instanceof PublicCloneable) {
        PublicCloneable pc = (PublicCloneable) this.drawingSupplier;
        try {
            clone.drawingSupplier = (DrawingSupplier) pc.clone();
        }
        catch (CloneNotSupportedException e) {
            throw new RuntimeException(e);
        }
    }
    return clone;
}

 * @param g  the graphics device for drawing on.
 */
@Override
public void paintComponent(Graphics g) {
    super.paintComponent(g);
    if (this.chart == null) {
        return;
    }
    Graphics2D g2 = (Graphics2D) g.create();

    // first determine the size of the chart rendering area...
    Dimension size = getSize();
    Insets insets = getInsets();
    Rectangle2D available = new Rectangle2D.Double(insets.left, insets.top,
            size.getWidth() - insets.left - insets.right,
            size.getHeight() - insets.top - insets.bottom);

    // work out if scaling is required...
    boolean scale = false;
    double drawWidth = available.getWidth();
    double drawHeight = available.getHeight();
    this.scaleX = 1.0;
    this.scaleY = 1.0;

    if (drawWidth < this.minimumDrawWidth) {
        this.scaleX = drawWidth / this.minimumDrawWidth;
        drawWidth = this.minimumDrawWidth;
        scale = true;
    }
    else if (drawWidth > this.maximumDrawWidth) {
        this.scaleX = drawWidth / this.maximumDrawWidth;
        drawWidth = this.maximumDrawWidth;
        scale = true;
    }

    if (drawHeight < this.minimumDrawHeight) {
        this.scaleY = drawHeight / this.minimumDrawHeight;
        drawHeight = this.minimumDrawHeight;
        scale = true;
    }
    else if (drawHeight > this.maximumDrawHeight) {
        this.scaleY = drawHeight / this.maximumDrawHeight;
        drawHeight = this.maximumDrawHeight;
        scale = true;
    }

    Rectangle2D chartArea = new Rectangle2D.Double(0.0, 0.0, drawWidth,
            drawHeight);

    // are we using the chart buffer?
    if (this.useBuffer) {

        // do we need to resize the buffer?
        if ((this.chartBuffer == null)
                || (this.chartBufferWidth != available.getWidth())
                || (this.chartBufferHeight != available.getHeight())) {
            this.chartBufferWidth = (int) available.getWidth();
            this.chartBufferHeight = (int) available.getHeight();
            GraphicsConfiguration gc = g2.getDeviceConfiguration();
            this.chartBuffer = gc.createCompatibleImage(
                    this.chartBufferWidth, this.chartBufferHeight,
                    Transparency.TRANSLUCENT);
            this.refreshBuffer = true;
        }

        // do we need to redraw the buffer?
        if (this.refreshBuffer) {

            this.refreshBuffer = false; // clear the flag

            Rectangle2D bufferArea = new Rectangle2D.Double(
                    0, 0, this.chartBufferWidth, this.chartBufferHeight);

            // make the background of the buffer clear and transparent
            Graphics2D bufferG2 = (Graphics2D)
                    this.chartBuffer.getGraphics();
            Composite savedComposite = bufferG2.getComposite();
            bufferG2.setComposite(AlphaComposite.getInstance(
                    AlphaComposite.CLEAR, 0.0f));
            Rectangle r = new Rectangle(0, 0, this.chartBufferWidth,
                    this.chartBufferHeight);
            bufferG2.fill(r);
            bufferG2.setComposite(savedComposite);

            if (scale) {
                AffineTransform saved = bufferG2.getTransform();
                AffineTransform st = AffineTransform.getScaleInstance(
                        this.scaleX, this.scaleY);
                bufferG2.transform(st);
                this.chart.draw(bufferG2, chartArea, this.anchor,
                        this.info);
                bufferG2.setTransform(saved);
            } else {
                this.chart.draw(bufferG2, bufferArea, this.anchor,
                        this.info);
            }

        }

        // zap the buffer onto the panel...
        g2.drawImage(this.chartBuffer, insets.left, insets.top, this);

    } else { // redrawing the chart every time...
        AffineTransform saved = g2.getTransform();
        g2.translate(insets.left, insets.top);
        if (scale) {
            AffineTransform st = AffineTransform.getScaleInstance(
                    this.scaleX, this.scaleY);
            g2.transform(st);
        }
        this.chart.draw(g2, chartArea, this.anchor, this.info);
        g2.setTransform(saved);

    }

    Iterator iterator = this.overlays.iterator();
    while (iterator.hasNext()) {
        Overlay overlay = (Overlay) iterator.next();
        overlay.paintOverlay(g2, this);
    }

    // redraw the zoom rectangle (if present) - if useBuffer is false,
    // we use XOR so we can XOR the rectangle away again without redrawing
    // the chart
    drawZoomRectangle(g2, !this.useBuffer);

    g2.dispose();

    this.anchor = null;
    this.verticalTraceLine = null;
    this.horizontalTraceLine = null;
}

