	// Commandline parser class
	private static class CommandlineParser
	{
		public CommandlineOptions parse(String[] args)
		{
			CommandlineOptions options = new CommandlineOptions();
			boolean endOpts = false;

			for(int i = 0; i < args.length; i++)
			{
				String arg = args[i];
				if(arg == null || arg.length() == 0)
				{
					args[i] = null;
					continue;
				}

				if(arg.startsWith("-") && !endOpts)
				{
					if(arg.equals("--"))
						endOpts = true;
					else if(parseOption(options, arg, args, i))
						args[i] = null;
				}
			}

			return options;
		}

		private boolean parseOption(CommandlineOptions options, String arg,
					String[] args, int i)
		{
			if(arg.equals("-usage"))
			{
				version();
				System.err.println();
				usage();
				System.exit(1);
			}
			else if(arg.equals("-version"))
			{
				version();
				System.exit(1);
			}
			else if(arg.equals("-nosettings"))
				options.settingsDirectory = null;
			else if(arg.startsWith("-settings="))
				options.settingsDirectory = arg.substring(10);
			else if(arg.startsWith("-noserver"))
				options.portFile = null;
			else if(arg.equals("-server"))
				options.portFile = "server";
			else if(arg.startsWith("-server="))
				options.portFile = arg.substring(8);
			else if(arg.startsWith("-background"))
				options.background = true;
			else if(arg.equals("-nogui"))
				options.gui = false;
			else if(arg.equals("-norestore"))
				options.restore = false;
			else if(arg.equals("-noplugins"))
				options.noPlugins = true;
			else if(arg.equals("-nostartupscripts"))
				options.noStartupScripts = true;
			else if(arg.startsWith("-run="))
				options.scriptFile = arg.substring(5);
			else if(Character.isDigit(arg.charAt(0)) && arg.length() == 1)
			{
				options.logLevel = Integer.parseInt(arg);
				args[i] = null;
			}
			else
			{
				System.err.println("Unknown option: " + arg);
				usage();
				System.exit(1);
			}

			return true;
		}
	}

	// Commandline handling methods
	private static boolean connectToServer(String portFile, boolean restore, String[] args, String scriptFile)
	{
		try
		{
			BufferedReader in = new BufferedReader(new FileReader(portFile));
			String check = in.readLine();
			if(!check.equals("b"))
				throw new Exception("Wrong port file format");

			int port = Integer.parseInt(in.readLine());
			int key = Integer.parseInt(in.readLine());
			in.close();

			Socket socket = new Socket(InetAddress.getByName("127.0.0.1"), port);
			DataOutputStream out = new DataOutputStream(
				socket.getOutputStream());
			out.writeInt(key);

			String script = makeServerScript(restore, args, scriptFile);
			out.writeUTF(script);

			out.close();
			return true;
		}
		catch(Exception e)
		{
			Log.log(Log.NOTICE, jEdit.class, "An error occurred"
				+ " while connecting to the jEdit server instance.");
			Log.log(Log.NOTICE, jEdit.class, "This probably means that"
				+ " jEdit crashed and/or exited abnormally");
			Log.log(Log.NOTICE, jEdit.class, "the last time it was run.");
			Log.log(Log.NOTICE, jEdit.class, "If you don't"
				+ " know what this means, don't worry.");
			Log.log(Log.NOTICE, jEdit.class, e);
			return false;
		}
	}

	private static void initializeSettingsDirectory(String settingsDir)
	{
		if(settingsDir == null)
			return;

		File dir = new File(settingsDir);
		if(!dir.exists())
			dir.mkdirs();

		File macrosDir = new File(settingsDir, "macros");
		if(!macrosDir.exists())
			macrosDir.mkdir();
	}

	private static Writer getLogWriter(String settingsDir)
	{
		if(settingsDir == null)
			return null;

		String logPath = MiscUtilities.constructPath(settingsDir, "activity.log");
		File logFile = new File(logPath);
		backupSettingsFile(logFile);

		try
		{
			return new BufferedWriter(new FileWriter(logFile));
		}
		catch(Exception e)
		{
			e.printStackTrace();
			return null;
		}
	}

	private static void initServer(String portFile, boolean background)
	{
		if(portFile != null)
		{
			server = new EditServer(portFile);
			if(!server.isOK())
				server = null;
		}
		else if(background)
		{
			System.err.println("You cannot specify both the"
				+ " -background and -noserver switches");
		}
	}

	private static void runStartupScripts(boolean noStartupScripts)
	{
		if(noStartupScripts)
			return;

		if(jEditHome != null)
			runStartupScripts(new File(MiscUtilities.constructPath(jEditHome, "startup")));

		if(settingsDirectory != null)
		{
			File startupDir = new File(MiscUtilities.constructPath(settingsDirectory, "startup"));
			if(!startupDir.exists())
				startupDir.mkdirs();
			runStartupScripts(startupDir);
		}
	}

	private static void runStartupScript(String scriptFile, String userDir)
	{
		if(scriptFile == null)
			return;

		scriptFile = MiscUtilities.constructPath(userDir, scriptFile);
		BeanShell.runScript(null, scriptFile, null, false);
	}

