	//{{{ restoreOpenFiles() method
	/**
	 * Opens files that were open last time.
	 * @since jEdit 3.2pre2
	 */
	public static String restoreOpenFiles()
	{
		return restoreOpenFiles(settingsDirectory != null, settingsDirectory,
			bufferCount == 0);
	}

	private static String restoreOpenFiles(boolean shouldRestore, String settingsDir, boolean shouldCreateNew)
	{
		if(!shouldRestore || settingsDir == null)
			return null;

		File session = new File(MiscUtilities.constructPath( settingsDir,"session"));
		if(!session.exists())
			return null;

		String splitConfig = null;

		try
		{
			BufferedReader in = new BufferedReader(new FileReader(session));
			String line;
			while((line = in.readLine()) != null)
			{
				if(line.startsWith("splits\t"))
					splitConfig = line.substring(7);
				else
					openFile(null,line);
			}

			in.close();
		}
		catch(IOException io)
		{
			Log.log(Log.ERROR, jEdit.class, "Error while loading " + session);
			Log.log(Log.ERROR, jEdit.class, io);
		}

		return splitConfig;
	} //}}}

