	//{{{ saveSettings() method
	/**
	 * Saves all user preferences to disk.
	 */
	public static void saveSettings()
	{
		if(settingsDirectory == null)
			return;

		File recentFile = new File(MiscUtilities.constructPath(
			settingsDirectory, "recent.xml"));
		if(!recentFile.exists() || recentFile.lastModified() == recentModTime)
		{
			File tempFile = new File(MiscUtilities.constructPath(
				settingsDirectory, "#recent.xml#save#"));
			backupSettingsFile(recentFile);
			BufferHistory.save(tempFile);
			recentFile.delete();
			tempFile.renameTo(recentFile);
			recentModTime = recentFile.lastModified();
		}

		File historyFile = new File(MiscUtilities.constructPath(
			settingsDirectory, "history"));
		if(!historyFile.exists() || historyFile.lastModified() == historyModTime)
		{
			File tempFile = new File(MiscUtilities.constructPath(
				settingsDirectory, "#history#save#"));
			backupSettingsFile(historyFile);
			HistoryModel.saveHistory(tempFile);
			historyFile.delete();
			tempFile.renameTo(historyFile);
			historyModTime = historyFile.lastModified();
		}

		SearchAndReplace.save();
		Abbrevs.save();
		FavoritesVFS.saveFavorites();

		File propsFile = new File(MiscUtilities.constructPath(
			settingsDirectory,"properties"));
		if(!propsFile.exists() || propsFile.lastModified() == propsModTime)
		{
			File tempFile = new File(MiscUtilities.constructPath(
				settingsDirectory,"#properties#save#"));
			backupSettingsFile(propsFile);

			try
			{
				OutputStream out = new FileOutputStream(tempFile);
				props.store(out,"jEdit properties");
				out.close();
			}
			catch(IOException io)
			{
				Log.log(Log.ERROR, jEdit.class, io);
			}

			propsFile.delete();
			tempFile.renameTo(propsFile);
			propsModTime = propsFile.lastModified();
		}
	} //}}}

	//{{{ exit() method
	/**
	 * Exits cleanly from jEdit, prompting the user if any unsaved files
	 * should be saved first.
	 * @param view The view from which this exit was called
	 * @param reallyExit If background mode is enabled and this parameter
	 * is true, then jEdit will close all open views instead of exiting
	 * entirely.
	 */
	public static void exit(View view, boolean reallyExit)
	{
		VFSManager.waitForRequests();
		EditBus.send(new EditorExitRequested(view));

		reallyExit |= !background;
		saveOpenFiles(view);

		if(!closeAllBuffers(view,reallyExit))
			return;

		if(!reallyExit)
		{
			view = viewsFirst;
			while(view != null)
			{
				closeView(view,false);
				view = view.next;
			}

			saveSettings();
			return;
		}

		view.close();
		Autosave.stop();

		if(server != null)
			server.stopServer();

		EditPlugin[] plugins = getPlugins();
		for(int i = 0; i < plugins.length; i++)
		{
			try
			{
				plugins[i].stop();
			}
			catch(Throwable t)
			{
				Log.log(Log.ERROR, jEdit.class, "Error while stopping plugin:");
				Log.log(Log.ERROR, jEdit.class, t);
			}
		}

		EditBus.send(new EditorExiting(null));
		saveSettings();
		Log.closeStream();
		System.exit(0);
	} //}}}

