def _get_form_field_names(form_class):
    """Return list of field names for a ModelForm class."""
    return list(form_class.base_fields)


def _get_form_field_names_for_model(model, fields=None, exclude=None):
    """Return list of field names for a model using fields_for_model."""
    return list(fields_for_model(model, fields=fields, exclude=exclude).keys())


