def _create_article_instance(headline, slug, pub_date, writer, article, categories=None, status=None):
    """Create and return an Article instance with given values."""
    article_obj = Article.objects.create(
        headline=headline, slug=slug, pub_date=pub_date, writer=writer, article=article
    )
    if status:
        article_obj.status = status
        article_obj.save()
    if categories:
        article_obj.categories.set(categories)
    return article_obj


