    /**
     * Returns a string for the tooltip.
     *
     * @param e  the mouse event.
     *
     * @return A tool tip or <code>null</code> if no tooltip is available.
     */
    @Override
    public String getToolTipText(MouseEvent e) {
        String result = null;
        if (this.info != null) {
            EntityCollection entities = this.info.getEntityCollection();
            if (entities != null) {
                Insets insets = getInsets();
                ChartEntity entity = entities.getEntity(
                        (int) ((e.getX() - insets.left) / this.scaleX),
                        (int) ((e.getY() - insets.top) / this.scaleY));
                if (entity != null) {
                    result = entity.getToolTipText();
                }
            }
        }
        return result;
    }

    /**
     * Translates a Java2D point on the chart to a screen location.
     *
     * @param java2DPoint  the Java2D point.
     *
     * @return The screen location.
     */
    public Point translateJava2DToScreen(Point2D java2DPoint) {
        Insets insets = getInsets();
        int x = (int) (java2DPoint.getX() * this.scaleX + insets.left);
        int y = (int) (java2DPoint.getY() * this.scaleY + insets.top);
        return new Point(x, y);
    }

    /**
     * Translates a panel (component) location to a Java2D point.
     *
     * @param screenPoint  the screen location (<code>null</code> not
     *                     permitted).
     *
     * @return The Java2D coordinates.
     */
    public Point2D translateScreenToJava2D(Point screenPoint) {
        Insets insets = getInsets();
        double x = (screenPoint.getX() - insets.left) / this.scaleX;
        double y = (screenPoint.getY() - insets.top) / this.scaleY;
        return new Point2D.Double(x, y);
    }

    /**
     * Applies any scaling that is in effect for the chart drawing to the
     * given rectangle.
     *
     * @param rect  the rectangle (<code>null</code> not permitted).
     *
     * @return A new scaled rectangle.
     */
    public Rectangle2D scale(Rectangle2D rect) {
        Insets insets = getInsets();
        double x = rect.getX() * getScaleX() + insets.left;
        double y = rect.getY() * getScaleY() + insets.top;
        double w = rect.getWidth() * getScaleX();
        double h = rect.getHeight() * getScaleY();
        return new Rectangle2D.Double(x, y, w, h);
    }

    /**
     * Returns the chart entity at a given point.
     * <P>
     * This method will return null if there is (a) no entity at the given
     * point, or (b) no entity collection has been generated.
     *
     * @param viewX  the x-coordinate.
     * @param viewY  the y-coordinate.
     *
     * @return The chart entity (possibly <code>null</code>).
     */
    public ChartEntity getEntityForPoint(int viewX, int viewY) {

        ChartEntity result = null;
        if (this.info != null) {
            Insets insets = getInsets();
            double x = (viewX - insets.left) / this.scaleX;
            double y = (viewY - insets.top) / this.scaleY;
            EntityCollection entities = this.info.getEntityCollection();
            result = entities != null ? entities.getEntity(x, y) : null;
        }
        return result;

    }

    /**
     * Returns the flag that controls whether or not the offscreen buffer
     * needs to be refreshed.
     *
     * @return A boolean.
     */
    public boolean getRefreshBuffer() {
        return this.refreshBuffer;
    }

    /**
     * Sets the refresh buffer flag.  This flag is used to avoid unnecessary
     * redrawing of the chart when the offscreen image buffer is used.
     *
     * @param flag  <code>true</code> indicates that the buffer should be
     *              refreshed.
     */
    public void setRefreshBuffer(boolean flag) {
        this.refreshBuffer = flag;
    }

    /**
     * Paints the component by drawing the chart to fill the entire component,
     * but allowing for the insets (which will be non-zero if a border has been
     * set for this component).  To increase performance (at the expense of
     * memory), an off-screen buffer image can be used.
     *
     * @param g  the graphics device for drawing on.
     */
    @Override
    public void paintComponent(Graphics g) {
        super.paintComponent(g);
        if (this.chart == null) {
            return;
        }
        Graphics2D g2 = (Graphics2D) g.create();

        // first determine the size of the chart rendering area...
        Dimension size = getSize();
        Insets insets = getInsets();
        Rectangle2D available = new Rectangle2D.Double(insets.left, insets.top,
                size.getWidth() - insets.left - insets.right,
                size.getHeight() - insets.top - insets.bottom);

        // work out if scaling is required...
        calculateScaling(available);

        Rectangle2D chartArea = new Rectangle2D.Double(0.0, 0.0, drawWidth,
                drawHeight);

        if (this.useBuffer) {
            manageChartBuffer(g2);
            drawZoomRectangle(g2, false);
        } else {
            redrawBufferlessChart(g2, chartArea);
        }

        drawOverlays(g2);
        drawZoomRectangle(g2, !this.useBuffer);

        g2.dispose();

        this.anchor = null;
        this.verticalTraceLine = null;
        this.horizontalTraceLine = null;
    }

    /**
     * Calculates the scaling factor and drawing dimensions for the chart
     * based on the available area and the configured minimum/maximum drawing
     * bounds. This method updates the instance variables scaleX, scaleY,
     * drawWidth, drawHeight, and scale flag.
     *
     * @param available the available drawing area
     */
    private void calculateScaling(Rectangle2D available) {
        boolean scale = false;
        drawWidth = available.getWidth();
        drawHeight = available.getHeight();
        scaleX = 1.0;
        scaleY = 1.0;

        if (drawWidth < minimumDrawWidth) {
            scaleX = drawWidth / minimumDrawWidth;
            drawWidth = minimumDrawWidth;
            scale = true;
        } else if (drawWidth > maximumDrawWidth) {
            scaleX = drawWidth / maximumDrawWidth;
            drawWidth = maximumDrawWidth;
            scale = true;
        }

        if (drawHeight < minimumDrawHeight) {
            scaleY = drawHeight / minimumDrawHeight;
            drawHeight = minimumDrawHeight;
            scale = true;
        } else if (drawHeight > maximumDrawHeight) {
            scaleY = drawHeight / maximumDrawHeight;
            drawHeight = maximumDrawHeight;
            scale = true;
        }

        isScalingRequired = scale;
    }

    /**
     * Manages the chart buffer for optimized drawing. This includes resizing
     * the buffer when dimensions change andredrawing the chart into the buffer
     * when needed.
     *
     * @param g2 the graphics context
     */
    private void manageChartBuffer(Graphics2D g2) {
        if (needsBufferResize()) {
            resizeChartBuffer(g2);
        }
        drawChartIntoBuffer();
        drawBufferedImage(g2);
    }

    /**
     * Determines whether the chart buffer needs to be resized based on the
     * current available drawing area dimensions.
     *
     * @return true if the buffer needs to be resized
     */
    private boolean needsBufferResize() {
        return (chartBuffer == null
                || chartBufferWidth != (int) available.getWidth()
                || chartBufferHeight != (int) available.getHeight());
    }

    /**
     * Resizes the chart buffer to match the current available drawing area
     * and sets the refresh flag to ensure a redraw.
     *
     * @param g2 the graphics context
     */
    private void resizeChartBuffer(Graphics2D g2) {
        chartBufferWidth = (int) available.getWidth();
        chartBufferHeight = (int) available.getHeight();
        GraphicsConfiguration gc = g2.getDeviceConfiguration();
        chartBuffer = gc.createCompatibleImage(
                chartBufferWidth, chartBufferHeight,
                Transparency.TRANSLUCENT);
        refreshBuffer = true;
    }

    /**
     * Draws the chart into thechart buffer, applying scaling if necessary.
     */
    private void drawChartIntoBuffer() {
        if (refreshBuffer) {
            refreshBuffer = false;

            Rectangle2D bufferArea = new Rectangle2D.Double(
                    0, 0, chartBufferWidth, chartBufferHeight);

            Graphics2D bufferG2 = (Graphics2D) chartBuffer.getGraphics();
            Composite savedComposite = bufferG2.getComposite();
            bufferG2.setComposite(AlphaComposite.getInstance(
                    AlphaComposite.CLEAR, 0.0f));
            Rectangle r = new Rectangle(0, 0, chartBufferWidth, chartBufferHeight);
            bufferG2.fill(r);
            bufferG2.setComposite(savedComposite);

            if (isScalingRequired) {
                AffineTransform saved = bufferG2.getTransform();
                AffineTransform st = AffineTransform.getScaleInstance(
                        scaleX, scaleY);
                bufferG2.transform(st);
                chart.draw(bufferG2, chartArea, anchor, info);
                bufferG2.setTransform(saved);
            } else {
                chart.draw(bufferG2, bufferArea, anchor, info);
            }
        }
    }

    /**
     * Draws the buffered image onto the main graphics context.
     *
     * @param g2 the main graphics context
     */
    private void drawBufferedImage(Graphics2D g2) {
        g2.drawImage(chartBuffer, insets.left, insets.top, this);
    }

    /**
     * Redraws the chart directly without using a buffer, applying scaling if
     * necessary.
     *
     * @param g2 the graphics context
     * @param chartArea the chart drawing area
     */
    private void redrawBufferlessChart(Graphics2D g2, Rectangle2D chartArea) {
        AffineTransform saved = g2.getTransform();
        g2.translate(insets.left, insets.top);
        if (isScalingRequired) {
            AffineTransform st = AffineTransform.getScaleInstance(
                    scaleX, scaleY);
            g2.transform(st);
        }
        chart.draw(g2, chartArea, anchor, info);
        g2.setTransform(saved);
    }

    /**
     * Draws all registered overlays on the panel using the provided graphics
     * context.
     *
     * @param g2 the graphics context
     */
    private void drawOverlays(Graphics2D g2) {
        Iterator iterator = overlays.iterator();
        while (iterator.hasNext()) {
            Overlay overlay = (Overlay) iterator.next();
            overlay.paintOverlay(g2, this);
        }
    }

    // Temporary variables to reduce method complexity and pass state efficiently
    private boolean isScalingRequired = false;
    private double drawWidth, drawHeight;
    private Rectangle2D available;
    private Rectangle2D chartArea;
    private Point2D anchor;
    private Insets insets;
    private double scaleX, scaleY;
    private int chartBufferWidth, chartBufferHeight;
    private Image chartBuffer;
    private boolean refreshBuffer;

    /**
     * Receives notification of changes to the chart, and redraws the chart.
     *
     * @param event  details of the chart change event.
     */
    @Override
    public void chartChanged(ChartChangeEvent event) {
        this.refreshBuffer = true;
        Plot plot = this.chart.getPlot();
        if (plot instanceof Zoomable) {
            Zoomable z = (Zoomable) plot;
            this.orientation = z.getOrientation();
        }
        repaint();
    }

